// qppExpect is one QA-authored, hand-derived expectation for a TV fixture. Fields
// are derived from the filename per parseTV's documented semantics; a zero
// episodeEnd/resolution/releaseGroup means that key must be ABSENT from the
// plugin's namespace (so the test catches a key that should not be there).
type qppExpect struct {
	rel          string
	title        string
	season       int
	episode      int
	episodeEnd   int // >0 => sources.tv-parser.episode_end must equal this; 0 => absent
	resolution   string
	releaseGroup string
	enriched     bool // false => tv-parser must skip (no SxxExx) and status stays "new"
}

// qppTVExpectations is the INDEPENDENTLY derived expectation table. Each row's
// values were computed by hand from the filename:
//   - the ASCII S<digits>E<digits>(E<digits>)? token -> season/episode (+episode_end)
//   - the title is the prefix before that token, with "."/"_"->" " and trimmed
//   - a 2160p/1080p/720p token (anywhere) -> resolution
//   - a trailing "-<token>" after SxxExx -> release_group
//
// The set is deliberately DISTINCT from the coder golden (Show.Name.S01E02.1080p /
// Игра престолов S01E01) and from scan-library (Breaking Bad / Игра престолов
// S01E01). A coder bug that emits wrong numbers is caught because nothing here is
// computed by the plugin or the coder's derivation.
var qppTVExpectations = []qppExpect{
	{rel: "Stranger.Things.S03E04.720p-WEB.mkv", title: "Stranger Things", season: 3, episode: 4, resolution: "720p", releaseGroup: "WEB", enriched: true},
	{rel: "Тьма S02E05.mkv", title: "Тьма", season: 2, episode: 5, enriched: true},
	{rel: "Frieren.S01E01E02.1080p.mkv", title: "Frieren", season: 1, episode: 1, episodeEnd: 2, resolution: "1080p", enriched: true},
	{rel: "Standup Special 2019.mkv", enriched: false}, // no SxxExx -> tv-parser applies=false -> skipped -> status new
}

// qppLegalStatuses is the canonical lifecycle set (acceptance.md state machine).
// Authored here independently of internal/enrich/state.go; the test only asserts
// observed statuses are a SUBSET (black-box: it cannot see the unexported set).
var qppLegalStatuses = []string{"new", "pending", "parsed", "enriched", "failed", "deleted"}

func TestQA_PipelineAcceptanceReDerivation(t *testing.T) {
	if testing.Short() {
		t.Skip("QA pipeline acceptance: skips under -short (builds binaries + subprocess)")
	}
	if _, err := exec.LookPath("ffprobe"); err != nil {
		t.Skip("ffprobe not on PATH — skipping QA acceptance re-derivation (INV-skip-clean)")
	}
	if _, err := exec.LookPath("ffmpeg"); err != nil {
		t.Skip("ffmpeg not on PATH — cannot generate the real media fixtures this test requires")
	}

	tmp := t.TempDir()
	serverBin := buildBinary(t, tmp, "qpp-server", "./cmd/mellifera")
	scannerBin := buildBinary(t, tmp, "qpp-base-scanner", "./plugins/base-scanner")
	tvParserBin := buildBinary(t, tmp, "qpp-tv-parser", "./plugins/tv-parser")
	fixtureRoot := qppWriteFixtures(t)

	token := "qpp-acceptance-token"
	baseURL := startServer(t, serverBin, scannerBin, tvParserBin, tmp, token)
	client := &http.Client{Timeout: httpTimeout}

	libID := createLibrary(t, client, baseURL, token, fixtureRoot)
	res := scanLibrary(t, client, baseURL, token, libID)

	if res.Discovered != len(qppTVExpectations) {
		t.Fatalf("AC-1: discovered = %d, want %d (one real .mkv per fixture)", res.Discovered, len(qppTVExpectations))
	}
	if res.Persisted != len(qppTVExpectations) {
		t.Fatalf("AC-1: persisted = %d, want %d", res.Persisted, len(qppTVExpectations))
	}

	byRel := indexByPath(t, listItems(t, client, baseURL, token, libID))

	t.Run("AC1_rederive_sources_and_split", func(t *testing.T) { qppAssertSources(t, byRel) })
	t.Run("AC5_provenance_and_view", func(t *testing.T) { qppAssertProvenance(t, byRel) })
	t.Run("AC1_stages_stage_literal", func(t *testing.T) { qppAssertStagesLiteral(t, byRel) })
	t.Run("AC7_lifecycle_and_filter", func(t *testing.T) {
		qppAssertLifecycle(t, client, baseURL, token, libID, byRel)
	})
	t.Run("AC6_softfail_unloaded_enrichers", func(t *testing.T) { qppAssertSoftFail(t, res) })
	t.Run("namespace_cleanliness", func(t *testing.T) { qppAssertNamespaceClean(t, byRel) })

	// Idempotent re-scan: upsert by file_id, no duplicates, statuses stable.
	second := scanLibrary(t, client, baseURL, token, libID)
	if second.Persisted != res.Persisted {
		t.Fatalf("re-scan persisted = %d, want %d (idempotent upsert by file_id)", second.Persisted, res.Persisted)
	}
	if got := len(listItems(t, client, baseURL, token, libID)); got != len(byRel) {
		t.Fatalf("re-scan changed item count: %d -> %d (expected idempotent)", len(byRel), got)
	}
}

// qppWriteFixtures generates one real (ffmpeg) media file per expectation at the
// library root. All are probeable; the AC-6 soft-fail here is the UNLOADED
// enrichers (kinopoisk/tmdb), not an unprobeable file.
func qppWriteFixtures(t *testing.T) string {
	t.Helper()
	root := t.TempDir()
	for _, e := range qppTVExpectations {
		makeMedia(t, filepath.Join(root, e.rel))
	}
	return root
}

// qppAssertSources re-derives AC-1: for every enriched fixture sources["tv-parser"]
// equals the hand-derived table (title/season/episode/episode_end/resolution/
// release_group, incl. absence of optional keys); for the no-season fixture
// sources has NO tv-parser; and the parseTV split holds (parsed carries only
// media-type-agnostic base fields, never TV fields).
func qppAssertSources(t *testing.T, byRel map[string]itemDTO) {
	t.Helper()
	for _, e := range qppTVExpectations {
		it, ok := byRel[e.rel]
		if !ok {
			t.Errorf("AC-1: QA fixture %q not persisted; have %v", e.rel, qppPaths(byRel))
			continue
		}
		doc := qppParseDoc(t, it.Document)
		if e.enriched {
			qppAssertTVNamespace(t, e, doc)
		} else if _, leak := doc.Sources["tv-parser"]; leak {
			t.Errorf("AC-1: %q (no SxxExx) carries sources.tv-parser — tv-parser must skip non-TV files", e.rel)
		}
		qppAssertParseTVSplit(t, e.rel, doc)
	}
}

func qppAssertTVNamespace(t *testing.T, e qppExpect, doc qppDoc) {
	t.Helper()
	tv, ok := doc.Sources["tv-parser"]
	if !ok {
		t.Errorf("AC-1: %q sources.tv-parser missing (sources=%v)", e.rel, doc.Sources)
		return
	}
	if got := ipStr(tv, "title"); got != e.title {
		t.Errorf("AC-1: %q sources.tv-parser.title = %q, want %q", e.rel, got, e.title)
	}
	if got := ipInt(tv, "season"); got != e.season {
		t.Errorf("AC-1: %q sources.tv-parser.season = %d, want %d", e.rel, got, e.season)
	}
	if got := ipInt(tv, "episode"); got != e.episode {
		t.Errorf("AC-1: %q sources.tv-parser.episode = %d, want %d", e.rel, got, e.episode)
	}
	qppAssertOptInt(t, e.rel, "episode_end", tv, e.episodeEnd)
	qppAssertOptStr(t, e.rel, "resolution", tv, e.resolution)
	qppAssertOptStr(t, e.rel, "release_group", tv, e.releaseGroup)
}

// qppAssertOptInt asserts a numeric namespace field equals want when want>0, else
// that the field is ABSENT (so an unexpected episode_end is caught).
func qppAssertOptInt(t *testing.T, rel, field string, m map[string]any, want int) {
	t.Helper()
	if want <= 0 {
		if _, leak := m[field]; leak {
			t.Errorf("AC-1: %q sources.tv-parser.%s present, want absent", rel, field)
		}
		return
	}
	if got := ipInt(m, field); got != want {
		t.Errorf("AC-1: %q sources.tv-parser.%s = %d, want %d", rel, field, got, want)
	}
}

func qppAssertOptStr(t *testing.T, rel, field string, m map[string]any, want string) {
	t.Helper()
	if want == "" {
		if _, leak := m[field]; leak {
			t.Errorf("AC-1: %q sources.tv-parser.%s present, want absent", rel, field)
		}
		return
	}
	if got := ipStr(m, field); got != want {
		t.Errorf("AC-1: %q sources.tv-parser.%s = %q, want %q", rel, field, got, want)
	}
}

// qppAssertParseTVSplit is the structural/negative AC-1 proof: base-scanner's
// parsed namespace is media-type-agnostic — NO TV field leaks — while the path +
// extension base fields are present.
func qppAssertParseTVSplit(t *testing.T, rel string, doc qppDoc) {
	t.Helper()
	for _, bad := range []string{"season", "episode", "episode_end", "resolution", "release_group", "year", "title"} {
		if _, leak := doc.Parsed[bad]; leak {
			t.Errorf("AC-1 split: %q parsed.%s present — TV fields must come from tv-parser only", rel, bad)
		}
	}
	if got := ipStr(doc.Parsed, "relative_path"); got != rel {
		t.Errorf("AC-1 split: %q parsed.relative_path = %q, want %q", rel, got, rel)
	}
	if got := ipStr(doc.Parsed, "extension"); got != ".mkv" {
		t.Errorf("AC-1 split: %q parsed.extension = %q, want .mkv", rel, got)
	}
}

// qppAssertProvenance re-derives AC-5: each enriched field carries a _provenance
// entry naming tv-parser (with a non-empty version), and _view.title points at the
// value with source tv-parser.
func qppAssertProvenance(t *testing.T, byRel map[string]itemDTO) {
	t.Helper()
	for _, e := range qppTVExpectations {
		if !e.enriched {
			continue
		}
		it, ok := byRel[e.rel]
		if !ok {
			continue
		}
		doc := qppParseDoc(t, it.Document)
		for _, f := range []string{"title", "season", "episode"} {
			p, ok := doc.Provenance[f]
			if !ok {
				t.Errorf("AC-5: %q _provenance.%s missing", e.rel, f)
				continue
			}
			if got := ipStr(p, "plugin_id"); got != "tv-parser" {
				t.Errorf("AC-5: %q _provenance.%s.plugin_id = %q, want tv-parser", e.rel, f, got)
			}
			if got := ipStr(p, "plugin_version"); got == "" {
				t.Errorf("AC-5: %q _provenance.%s.plugin_version empty", e.rel, f)
			}
		}
		if v := doc.View["title"]; ipStr(v, "value") != e.title || ipStr(v, "source") != "tv-parser" {
			t.Errorf("AC-5: %q _view.title = %v, want {value:%q,source:tv-parser}", e.rel, doc.View["title"], e.title)
		}
	}
}

// qppAssertStagesLiteral pins the literal _stages.stage value ("metadata_source")
// the coder's golden deliberately does not pin (reviewer advisory). The impl uses
// "metadata_source" (contracts.md:132 "parse" was illustrative); pinning it here
// documents the actual contract value and catches a silent rename. It also
// re-asserts the tv-parser parse stage advanced the item to "parsed" with status ok.
func qppAssertStagesLiteral(t *testing.T, byRel map[string]itemDTO) {
	t.Helper()
	for _, e := range qppTVExpectations {
		if !e.enriched {
			continue
		}
		it, ok := byRel[e.rel]
		if !ok {
			continue
		}
		stages := qppParseDoc(t, it.Document).Stages
		if !qppStageHas(stages, "tv-parser", "metadata_source", "parsed", "ok") {
			t.Errorf("AC-1: %q no _stages {tv-parser, stage:metadata_source, advanced_to:parsed, ok}; stages=%v", e.rel, stages)
		}
	}
}

// qppAssertLifecycle re-derives AC-7: every persisted status is in the canonical
// legal set; ?status=enriched returns EXACTLY the TV-parsed fixtures (each with
// queryable tv-parser provenance); ?status=new returns the no-season fixture.
func qppAssertLifecycle(t *testing.T, c *http.Client, baseURL, token string, libID int64, byRel map[string]itemDTO) {
	t.Helper()
	for rel, it := range byRel {
		if !qppLegalStatus(it.Status) {
			t.Errorf("AC-7: %q status = %q, outside legal set %v", rel, it.Status, qppLegalStatuses)
		}
	}
	enrichedRels, newRels := qppPartition()
	enriched := ipItemsByStatus(t, c, baseURL, token, libID, "enriched")
	qppAssertStatusSet(t, "enriched", enriched, enrichedRels)
	for _, it := range enriched {
		if _, ok := qppParseDoc(t, it.Document).Sources["tv-parser"]; !ok {
			t.Errorf("AC-5: enriched item %q has no sources.tv-parser in filtered listing", it.RelativePath)
		}
	}
	qppAssertStatusSet(t, "new", ipItemsByStatus(t, c, baseURL, token, libID, "new"), newRels)
}

// qppAssertStatusSet asserts a ?status=<label> response contains EXACTLY wantRels
// (set equality) and every returned item carries that status.
func qppAssertStatusSet(t *testing.T, label string, items []itemDTO, wantRels []string) {
	t.Helper()
	got := make(map[string]bool, len(items))
	for _, it := range items {
		got[it.RelativePath] = true
		if it.Status != label {
			t.Errorf("AC-7: ?status=%s returned %q with status %q", label, it.RelativePath, it.Status)
		}
	}
	for _, rel := range wantRels {
		if !got[rel] {
			t.Errorf("AC-7: ?status=%s missing expected %q (got %v)", label, rel, qppItemPaths(items))
		}
	}
	if len(got) != len(wantRels) {
		t.Errorf("AC-7: ?status=%s returned %d items, want %d (got %v)", label, len(got), len(wantRels), qppItemPaths(items))
	}
}

// qppAssertSoftFail re-derives AC-6: the unloaded external enrichers (kinopoisk,
// tmdb) surface in scan warnings, yet the scan SUCCEEDED (reached here) and every
// TV fixture still reached enriched via tv-parser.
func qppAssertSoftFail(t *testing.T, res scanResponse) {
	t.Helper()
	if !ipWarnsAboutAll(res.Warnings, "kinopoisk", "tmdb") {
		t.Errorf("AC-6: scan warnings missing an unloaded-enricher soft-fail; warnings=%v", res.Warnings)
	}
}

// qppAssertNamespaceClean asserts the runtime consequence of core namespace
// enforcement (validateNamespace): in the persisted output, sources contains ONLY
// the loaded metadata_source id ("tv-parser") and every _provenance plugin_id is
// tv-parser. A foreign namespace leaking through would fail this.
func qppAssertNamespaceClean(t *testing.T, byRel map[string]itemDTO) {
	t.Helper()
	for rel, it := range byRel {
		doc := qppParseDoc(t, it.Document)
		for k := range doc.Sources {
			if k != "tv-parser" {
				t.Errorf("namespace: %q sources has foreign key %q (only tv-parser is loaded)", rel, k)
			}
		}
		for field, p := range doc.Provenance {
			if got := ipStr(p, "plugin_id"); got != "tv-parser" {
				t.Errorf("namespace: %q _provenance.%s.plugin_id = %q (only tv-parser is loaded)", rel, field, got)
			}
		}
	}
}

// qppStageHas reports whether stages has an entry matching pluginID plus, when
// non-empty, the literal stage / advanced_to / status. Unlike the coder's
// ipStageHas it also matches the stage string (the reviewer-advisory pin).
func qppStageHas(stages []map[string]any, pluginID, stage, advancedTo, status string) bool {
	for _, s := range stages {
		if ipStr(s, "plugin_id") != pluginID {
			continue
		}
		if stage != "" && ipStr(s, "stage") != stage {
			continue
		}
		if status != "" && ipStr(s, "status") != status {
			continue
		}
		if advancedTo != "" && ipStr(s, "advanced_to") != advancedTo {
			continue
		}
		return true
	}
	return false
}

func qppLegalStatus(s string) bool {
	for _, legal := range qppLegalStatuses {
		if s == legal {
			return true
		}
	}
	return false
}

// qppPartition splits the QA fixture rels into enriched vs new (the only two
// statuses this fixture set produces: TV files -> enriched, the no-season file -> new).
func qppPartition() (enriched, news []string) {
	for _, e := range qppTVExpectations {
		if e.enriched {
			enriched = append(enriched, e.rel)
		} else {
			news = append(news, e.rel)
		}
	}
	return enriched, news
}

func qppPaths(m map[string]itemDTO) []string {
	out := make([]string, 0, len(m))
	for k := range m {
		out = append(out, k)
	}
	return out
}

func qppItemPaths(items []itemDTO) []string {
	out := make([]string, 0, len(items))
	for _, it := range items {
		out = append(out, it.RelativePath)
	}
	return out
}

// qppDoc is the QA-authored navigation of the enriched document. It deliberately
// mirrors only the fields this witness asserts over (parsed/sources/_provenance/
// _view/_stages); expectations live in qppTVExpectations, not here.
type qppDoc struct {
	Parsed     map[string]any            `json:"parsed"`
	Sources    map[string]map[string]any `json:"sources"`
	Provenance map[string]map[string]any `json:"_provenance"`
	View       map[string]map[string]any `json:"_view"`
	Stages     []map[string]any          `json:"_stages"`
}

// qppParseDoc decodes a persisted Item document into the QA-owned shape. The
// assertions use this (not the coder's ipDoc) so the witness does not couple to
// the coder golden's document type; expectations live in qppTVExpectations.
func qppParseDoc(t *testing.T, raw json.RawMessage) qppDoc {
	t.Helper()
	var d qppDoc
	if err := json.Unmarshal(raw, &d); err != nil {
		t.Fatalf("qpp unmarshal document: %v (doc=%s)", err, raw)
	}
	return d
}
